/** Long-term progression: milestones, the vault, daily missions and guilds. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, infobox, recordTable, sections, table, titleCase } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context

  for (const tier of data.MILESTONE_TIER_DATA) {
    const waves = [...new Set([...tier.standard.waveRewards, ...tier.premium.waveRewards].map(row => row.wave))].sort((a, b) => a - b)
    const rewardsAt = (track, wave) => (track.waveRewards.find(row => row.wave === wave)?.rewards ?? []).join(', ')
    context.page(
      `Milestones: Tier ${tier.tier}`,
      sections(
        table(['Wave', 'Standard', 'Premium'], waves.map(wave => [wave, rewardsAt(tier.standard, wave), rewardsAt(tier.premium, wave)])),
        `Back to ${context.link('Milestones')}.`,
      ),
      { source: 'MILESTONE_TIER_DATA' },
    )
  }
  context.page(
    'Milestones',
    sections(
      heading(2, 'What Milestones Unlock'),
      recordTable(data.MILESTONE_SYSTEM_UNLOCK_ROWS, format, [['reward', 'Unlocks'], 'tier', 'wave']),
      table(['Unlocked another way', 'How'], Object.entries(data.NON_MILESTONE_GATES).map(([system, gate]) => [titleCase(system), gate])),
      heading(2, 'Totals By Tier'),
      table(
        ['Tier', 'Track', 'Coins', 'Gems', 'Stones'],
        data.MILESTONE_TOTAL_ROWS.map(row => [
          context.link(`Milestones: Tier ${row.tier}`, `Tier ${row.tier}`),
          titleCase(row.track),
          row.coinsText,
          row.gemsText,
          row.stonesText,
        ]),
      ),
    ),
    { source: ['MILESTONE_TOTAL_ROWS', 'MILESTONE_SYSTEM_UNLOCK_ROWS'] },
  )

  const trees = [
    ['Harmony', data.VAULT_V29_HARMONY],
    ['Power', data.VAULT_V29_POWER],
    ['Enemy', data.VAULT_V29_ENEMY],
  ]
  const sum = values => values.reduce((total, value) => total + value, 0)
  for (const [label, tree] of trees) {
    context.page(
      `Vault: ${label}`,
      sections(
        ...tree.categories.map(category => {
          const upgrades = tree.upgrades.filter(upgrade => upgrade.category === category.name)
          return sections(
            heading(2, category.name),
            infobox([
              ['Key cost to unlock', category.autoUnlocked ? 'Unlocked from the start' : category.unlockCost],
              ['Requires', (category.requirements ?? []).map(requirement => requirement.name).join(', ')],
            ]),
            table(
              ['Upgrade', 'Levels', 'Keys for the first level', 'Keys for all levels', 'Value at the last level', 'Unit'],
              upgrades.map(upgrade => [
                upgrade.name ?? `${upgrade.enemy}: ${upgrade.stat}`,
                upgrade.levelCosts.length,
                upgrade.levelCosts[0],
                format.value(sum(upgrade.levelCosts)),
                format.value(upgrade.levelValues.at(-1)),
                upgrade.unit,
              ]),
            ),
          )
        }),
        `Back to ${context.link('The Vault')}.`,
      ),
      { source: `VAULT_V29_${label.toUpperCase()}` },
    )
  }
  context.page(
    'The Vault',
    sections(
      context.overview('vault'),
      data.VAULT_V29_PROVENANCE,
      table(
        ['Tree', 'Categories', 'Upgrades', 'Keys for everything'],
        trees.map(([label, tree]) => [
          context.link(`Vault: ${label}`, label),
          tree.categories.length,
          tree.upgrades.length,
          format.value(sum(tree.upgrades.flatMap(upgrade => upgrade.levelCosts)) + sum(tree.categories.map(category => category.unlockCost))),
        ]),
      ),
    ),
    { source: ['VAULT_V29_HARMONY', 'VAULT_V29_POWER', 'VAULT_V29_ENEMY'] },
  )

  context.page(
    'Daily Missions',
    sections(
      context.overview('daily-missions'),
      heading(2, 'Missions'),
      recordTable(data.DAILY_MISSION_GOALS, format, [['missionType', 'Type'], ['text', 'Mission'], ['goals', 'Targets for {0}']]),
      heading(2, 'Rewards By Tier'),
      recordTable(data.DAILY_MISSION_TIER_REWARDS, format),
      heading(2, 'Weekly Rewards'),
      recordTable(data.DAILY_MISSION_WEEKLY_REWARDS, format),
      heading(3, 'Weekly Total'),
      table(['Reward', 'Total'], Object.entries(data.DAILY_MISSION_WEEKLY_TOTAL_BY_REWARD).map(([reward, total]) => [titleCase(reward), total])),
    ),
    { source: ['DAILY_MISSION_GOALS', 'DAILY_MISSION_TIER_REWARDS', 'DAILY_MISSION_WEEKLY_REWARDS'] },
  )

  const relicName = id => data.RELIC_TEMPLATES.find(relic => relic.id === id)?.name ?? id
  context.page(
    'Guild',
    sections(
      context.overview('guild'),
      heading(2, 'Weekly Chests'),
      table(
        ['Chest', 'Points needed', ...data.GUILD_CHEST_PAYOUTS.map(payout => payout.currency)],
        data.GUILD_CHEST_THRESHOLDS.map((threshold, index) => [index + 1, threshold, ...data.GUILD_CHEST_PAYOUTS.map(payout => payout.perBox[index])]),
      ),
      bullets(data.GUILD_CHEST_PAYOUTS.map(payout => `${payout.currency}: ${payout.total} from all chests`)),
      heading(2, 'Seasons'),
      table(['Season', 'Relics'], data.GUILD_SEASONS.map(season => [season.label, season.relicIds.map(relicName).join(', ')])),
      heading(3, 'Season Relic Cost'),
      table(['Rarity', 'Tokens'], Object.entries(data.GUILD_SEASON_RELIC_TOKEN_COST_BY_RARITY)),
      `See also ${context.link('Relics')} and ${context.link('Guardian')}.`,
    ),
    { source: ['GUILD_SEASONS', 'GUILD_CHEST_PAYOUTS', 'GUILD_CHEST_THRESHOLDS'] },
  )

  context.group('Progression', ['Milestones', 'The Vault', 'Daily Missions', 'Guild'])
}
